/**
 * useRecordParam — read and write a deep-link query parameter.
 *
 * The other half of `lib/recordLinks.js`: that file builds `?open=<id>`, this one
 * consumes it. A page that links out but doesn't read links in is only half
 * connected, which is how `/people?user=…` ended up being generated by global
 * search and ignored by the People page.
 *
 * Clearing matters as much as reading: a record opened from a link must be
 * closable, and the URL shouldn't keep reopening it on the next render or after a
 * refresh. `set` keeps the address bar in step with what's on screen so it stays
 * shareable, and replaces rather than pushes so deep links don't pile up in the
 * back button.
 */
import { useCallback } from "react";
import { useSearchParams } from "react-router-dom";

export default function useRecordParam(name) {
  const [params, setParams] = useSearchParams();
  const value = params.get(name);

  const set = useCallback((next) => {
    setParams((prev) => {
      const copy = new URLSearchParams(prev);
      if (next) copy.set(name, String(next));
      else copy.delete(name);
      return copy;
    }, { replace: true });
  }, [name, setParams]);

  return [value, set];
}
